"""Crude stdlib PDF text dump: inflate streams, pull text-show operators, one line per text-matrix move."""
import re, sys, zlib

def unescape(s: bytes) -> str:
    out = bytearray()
    i = 0
    while i < len(s):
        c = s[i]
        if c == 0x5C and i + 1 < len(s):
            n = s[i + 1]
            m = {ord('n'): 10, ord('r'): 13, ord('t'): 9, ord('b'): 8, ord('f'): 12,
                 ord('('): 40, ord(')'): 41, ord('\\'): 92}
            if n in m:
                out.append(m[n]); i += 2; continue
            if 48 <= n <= 55:
                j = i + 1; oct_ = b''
                while j < len(s) and len(oct_) < 3 and 48 <= s[j] <= 55:
                    oct_ += bytes([s[j]]); j += 1
                out.append(int(oct_, 8) & 255); i = j; continue
            i += 1; continue
        out.append(c); i += 1
    return out.decode('latin-1')

def page_text(data: bytes) -> str:
    lines, cur, last_y = [], [], None
    tok = re.compile(rb'\[((?:[^\]\\]|\\.)*)\]\s*TJ|\(((?:[^()\\]|\\.)*)\)\s*Tj|([-\d.]+)\s+([-\d.]+)\s+Td|[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+([-\d.]+)\s+Tm|\bET\b', re.S)
    for m in tok.finditer(data):
        if m.group(1) is not None:
            parts = re.findall(rb'\(((?:[^()\\]|\\.)*)\)', m.group(1), re.S)
            cur.append(''.join(unescape(p) for p in parts))
        elif m.group(2) is not None:
            cur.append(unescape(m.group(2)))
        elif m.group(5) is not None:
            y = m.group(5)
            if last_y is not None and y != last_y and cur:
                lines.append(' | '.join(x for x in cur if x.strip())); cur = []
            last_y = y
        elif m.group(3) is not None:
            if cur:
                lines.append(' | '.join(x for x in cur if x.strip())); cur = []
    if cur:
        lines.append(' | '.join(x for x in cur if x.strip()))
    return '\n'.join(l for l in lines if l.strip())

def main(path: str) -> None:
    raw = open(path, 'rb').read()
    for m in re.finditer(rb'stream\r?\n(.*?)\r?\nendstream', raw, re.S):
        body = m.group(1)
        try:
            body = zlib.decompress(body)
        except Exception:
            pass
        if b'Tj' in body or b'TJ' in body:
            print(page_text(body))
            print('--- page break ---')

if __name__ == '__main__':
    main(sys.argv[1])

