"""Read-only Microsoft Graph helper. Loads creds from the repo .env, never prints them. GET requests only."""
import base64, hashlib, json, os, sys, urllib.parse, urllib.request, urllib.error

ENV = "/Users/rama/git/rama-worktrial/.env"
OUT = "/private/tmp/claude-501/-Users-rama-git-rama-worktrial/4fa92646-869c-4c02-b329-d59b99bad2a1/scratchpad/mail_dl"


def load_env(path=ENV):
    for line in open(path):
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        os.environ.setdefault(k.strip(), v.strip())


load_env()
_token = None


def token():
    global _token
    if _token:
        return _token
    url = f"https://login.microsoftonline.com/{os.environ['GRAPH_TENANT_ID']}/oauth2/v2.0/token"
    body = urllib.parse.urlencode({
        "client_id": os.environ["GRAPH_CLIENT_ID"],
        "client_secret": os.environ["GRAPH_CLIENT_SECRET"],
        "scope": "https://graph.microsoft.com/.default",
        "grant_type": "client_credentials",
    }).encode()
    try:
        with urllib.request.urlopen(urllib.request.Request(url, data=body)) as r:
            _token = json.load(r)["access_token"]
    except urllib.error.HTTPError as e:
        print("TOKEN ERROR", e.code, e.read().decode()[:400])
        sys.exit(1)
    return _token


def get(path_or_url, params=None):
    url = path_or_url if path_or_url.startswith("http") else "https://graph.microsoft.com/v1.0" + path_or_url
    if params:
        url += ("&" if "?" in url else "?") + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"Authorization": "Bearer " + token(), "Prefer": 'outlook.body-content-type="text"'})
    try:
        with urllib.request.urlopen(req) as r:
            return json.load(r)
    except urllib.error.HTTPError as e:
        print("HTTP ERROR", e.code, url[:120], e.read().decode()[:300])
        return None


def get_all(path, params=None):
    data = get(path, params)
    while data:
        for item in data.get("value", []):
            yield item
        nxt = data.get("@odata.nextLink")
        data = get(nxt) if nxt else None


MB = None


def mbox():
    return "/users/" + urllib.parse.quote(os.environ["GRAPH_MAILBOX"])


def cmd_token_check():
    t = token()
    payload = t.split(".")[1] + "=="
    claims = json.loads(base64.urlsafe_b64decode(payload))
    print("token ok; roles:", claims.get("roles"), "| app:", claims.get("app_displayname"))


def cmd_folders():
    for f in get_all(mbox() + "/mailFolders", {"$top": 100}):
        print(f"{f['displayName']:<22} total={f['totalItemCount']:<5} unread={f['unreadItemCount']:<4} children={f['childFolderCount']} id={f['id'][:12]}…")
        if f["childFolderCount"]:
            for c in get_all(mbox() + f"/mailFolders/{f['id']}/childFolders", {"$top": 100}):
                print(f"  └ {c['displayName']:<20} total={c['totalItemCount']}")


def cmd_list(folder):
    os.makedirs(OUT, exist_ok=True)
    msgs = list(get_all(mbox() + f"/mailFolders/{folder}/messages", {
        "$top": 100, "$orderby": "receivedDateTime asc",
        "$select": "id,subject,from,toRecipients,receivedDateTime,sentDateTime,hasAttachments,conversationId,internetMessageId,isDraft",
    }))
    json.dump(msgs, open(f"{OUT}/{folder}.json", "w"), indent=1)
    print(len(msgs), "messages in", folder)
    for m in msgs:
        frm = (m.get("from") or {}).get("emailAddress", {}).get("address", "?")
        to = ",".join(r["emailAddress"]["address"] for r in m.get("toRecipients", []))[:40]
        print(f"{(m.get('receivedDateTime') or m.get('sentDateTime') or '')[:16]} att={int(m['hasAttachments'])} {frm[:34]:<34} -> {to:<40} | {(m['subject'] or '')[:70]}")


def cmd_attachments(folder):
    msgs = json.load(open(f"{OUT}/{folder}.json"))
    rows = []
    for m in msgs:
        if not m["hasAttachments"]:
            continue
        d = f"{OUT}/att/{folder}/{m['id'][-12:]}"
        os.makedirs(d, exist_ok=True)
        for a in get_all(mbox() + f"/messages/{m['id']}/attachments"):
            name = a.get("name") or "unnamed"
            safe = name.replace("/", "_")
            sha = None
            if a.get("@odata.type", "").endswith("fileAttachment") and a.get("contentBytes"):
                raw = base64.b64decode(a["contentBytes"])
                sha = hashlib.sha256(raw).hexdigest()
                open(f"{d}/{safe}", "wb").write(raw)
            rows.append({"msg": m["id"][-12:], "subject": m["subject"], "name": name, "type": a.get("contentType"), "size": a.get("size"), "inline": a.get("isInline"), "kind": a.get("@odata.type"), "sha256": sha})
    json.dump(rows, open(f"{OUT}/att_{folder}.json", "w"), indent=1)
    print(len(rows), "attachments in", folder)
    for r in rows:
        print(f"{r['msg']} {(r['subject'] or '')[:34]:<34} | {r['name'][:46]:<46} {r['type'] or '':<22} {r['size']:>7} {'inline' if r['inline'] else ''} {(r['sha256'] or '')[:10]}")


if __name__ == "__main__":
    c = sys.argv[1]
    {"token": cmd_token_check, "folders": cmd_folders, "list": lambda: cmd_list(sys.argv[2]), "attachments": lambda: cmd_attachments(sys.argv[2])}[c]()

