    if b.ack:
        v = b.ack.doc.header.customer_po_ref
        vals.append(("Ack", key(v.raw), v.raw, _ack_src(b, v)))
    return [compare("H.po_number", "2.3", "Customer PO number on the SO", vals, severity="high", what="PO number")]


