    """Country of origin with its source and strength: our supplier PO line (strong), then the
    item default (weak: it disagrees with lot origin on 83% of lots). Lot origin comes later."""
    sup = [p for p in b.supply if p.get("so_lin_no") == m.so["lin_no"]]
    if sup and sup[0].get("src_cntry"):
        p = sup[0]
        return p["src_cntry"], f"po_detl.src_cntry (PO {p['po_no']} line {p['lin_no']})", "strong"
    item = b.items.get((m.so["item_no"], m.so["manu_no"]))
    if item and item.get("deflt_cnty_of_origin"):
        return item["deflt_cnty_of_origin"], f"item.deflt_cnty_of_origin ({m.so['item_no']})", "weak"
