            best = max(cands, key=lambda s: difflib.SequenceMatcher(None, parse.mpn_key(pl.mpn.raw) or "", parse.mpn_key(s["item_no"])).ratio())
            so_free.remove(best)
            matches.append(LineMatch(po=pl, po_index=idx, so=best, near_miss=True))
        else:
            matches.append(LineMatch(po=pl, po_index=idx))
    matches += [LineMatch(so=s) for s in so_free]

    # Ack lines: the ack prints the SO line number.
    if b.ack:
        by_no = {}
        for al in b.ack.doc.lines:
            n = parse.num(al.line_no.raw)
            if n is not None:
                by_no[int(n)] = al
        for m in matches:
            if m.so and m.so["lin_no"] in by_no:
                m.ack = by_no[m.so["lin_no"]]

    quote_by_line = {ql["lin_no"]: ql for ql in b.quote_lines}
    for m in matches:
        if m.so and m.so.get("gen_quot_lin") in quote_by_line:
            m.quote = quote_by_line[m.so["gen_quot_lin"]]
    matches.sort(key=lambda m: (m.so["lin_no"] if m.so else 999, m.po_index or 0))
    return matches


def build(erp: Erp, po: Extracted | None, ack: Extracted | None, so_number: int | None = None) -> Bundle:
    b = Bundle(po=po, ack=ack, po_comma=_decimal_comma(po), ack_comma=_decimal_comma(ack))
    b.so, b.problems = resolve_so(erp, po, ack, so_number)
    if b.so:
        b.so_lines = q.so_lines(erp, b.so["order_no"])
        b.customer = q.customer(erp, b.so["cust_no"])
        quote_no = (b.so.get("quote_no") or "").strip()
        if quote_no.isdigit():
            b.quote = q.quote(erp, int(quote_no))
            b.quote_lines = q.quote_lines(erp, int(quote_no))
        b.supply = q.linked_po_lines(erp, b.so["order_no"])
        keys = sorted({(l["item_no"], l["manu_no"]) for l in b.so_lines})
        b.items = q.items(erp, keys)
        for k in keys:
            b.inventory[k] = q.inventory(erp, *k)
            b.lots[k] = q.lots(erp, *k)
            b.open_supply[k] = q.open_po_lines_for_item(erp, *k)
        po_nos = sorted({p["po_no"] for p in b.supply} | {p["po_no"] for rows in b.open_supply.values() for p in rows
                                                            if p.get("so_order_no") in (None, b.so["order_no"])})
        for po_no in po_nos:
            b.supplier_po_lines[po_no] = q.po_lines(erp, po_no)
        vend_nos = {l["vend_no"] for l in b.so_lines if l.get("vend_no")} | {p["vend_no"] for rows in b.supplier_po_lines.values() for p in rows}
        for v in sorted(vend_nos):
            b.vendors[v] = q.vendor(erp, v)
        _load_supplier_terms(b)
    if b.customer:
        b.open_orders = q.open_order_value(erp, b.customer["cust_no"])
        b.ar_balance = q.ar_balance(erp, b.customer["cust_no"])
        b.requirements += ledger.from_customer(b.customer)
    if po:
        b.requirements += ledger.from_document(po)
    b.requirements = ledger.llm_label(b.requirements)
    b.lines = match_lines(b)
    return b

"""The check registry and runner.

Every registered check runs on every order, in registration order. Then each clause type in
the order's requirements ledger is handed to its verifier. No model decides what runs.
"""
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from typing import Callable

from ..bundle import Bundle
from ..models import Evidence, Finding, Requirement, Status


@dataclass
class Check:
    id: str
    ref: str
    title: str
    fn: Callable[[Bundle], list[Finding]]


CHECKS: list[Check] = []
VERIFIERS: dict[str, Callable[[str, list[Requirement], Bundle], list[Finding]]] = {}


def check(id: str, ref: str, title: str):
    def deco(fn):
        CHECKS.append(Check(id, ref, title, fn))
        return fn
    return deco


def verifier(*clause_types: str):
    def deco(fn):
        for ct in clause_types:
            VERIFIERS[ct] = fn
        return fn
    return deco


def finding(check_id: str, ref: str, title: str, status: Status, message: str, evidence=(), severity="medium", line=None) -> Finding:
    if status in (Status.PASS, Status.INFO):
        severity = "info"
    return Finding(check_id=check_id, checklist_ref=ref, title=title, status=status, severity=severity,
                   message=message, evidence=list(evidence), line=line)


def ev(label: str, value, source: str) -> Evidence:
    return Evidence(label=label, value=None if value is None else str(value), source=source)


def req_evidence(reqs: list[Requirement]) -> list[Evidence]:
    return [ev("Clause", r.quote, r.source) for r in reqs]


def run(b: Bundle) -> list[Finding]:
    findings: list[Finding] = []
    for c in CHECKS:
        try:
            findings += c.fn(b) or []
        except Exception as e:  # a broken check must show up, not vanish
            findings.append(finding(c.id, c.ref, c.title, Status.UNVERIFIABLE, f"check failed to run: {e!r}", severity="high"))
    groups: dict[str, list[Requirement]] = defaultdict(list)
    for r in b.requirements:
        groups[r.clause_type].append(r)
    for clause_type, reqs in groups.items():
        fn = VERIFIERS.get(clause_type, VERIFIERS["__unknown__"])
        try:
            findings += fn(clause_type, reqs, b) or []
        except Exception as e:
            findings.append(finding(f"R.{clause_type}", "3.2", f"Requirement: {clause_type}", Status.UNVERIFIABLE,
                                    f"verifier failed to run: {e!r}", req_evidence(reqs), severity="high"))
    return findings


