"""Writes to the ERP: record check results, put an order on hold.

Dry-run by default (ERP_DRY_RUN=1): each action is planned, with its exact SQL, and logged to
the state store (visible at GET /erp-actions) but not executed. With ERP_DRY_RUN=0 the same
statements run in one transaction. Our own tables carry an `agent_` prefix; the only change to
an ERP table is the order status, and only from open (O, I) to hold (H).
"""
from __future__ import annotations

import json

from . import config, db, state

SCHEMA = [
    "create table if not exists worktrial.agent_check_result (id bigserial primary key, so_number integer, cust_no text, "
    "cust_po text, recommendation text, counts jsonb, report_path text, message_id text, created_at timestamptz default now())",
    "create table if not exists worktrial.agent_check_issue (result_id bigint references worktrial.agent_check_result(id), "
    "check_id text, checklist_ref text, title text, status text, severity text, line integer, message text)",
    "create table if not exists worktrial.agent_order_hold (id bigserial primary key, so_number integer, previous_status text, "
    "reason text, message_id text, created_at timestamptz default now())",
]

ISSUES = ("fail", "needs_approval", "needs_review", "unverifiable")


def record_result(result, message_id: str | None = None) -> dict:
    o = result.order
    if not o.get("so_number"):
        return {"skipped": "no SO"}
    head = ("insert into worktrial.agent_check_result (so_number, cust_no, cust_po, recommendation, counts, report_path, message_id) "
            "values (%s, %s, %s, %s, %s, %s, %s) returning id",
            [o["so_number"], o.get("cust_no"), o.get("cust_po"), result.recommendation, json.dumps(result.counts), result.report_path, message_id])
