async def verify_upload(po: UploadFile = File(...), ack: UploadFile | None = File(None)):
    """Verify uploaded documents (a customer PO, optionally its SO acknowledgement)."""
    from . import ingest, verify

    with tempfile.TemporaryDirectory() as d:
        po_path = Path(d) / Path(po.filename or "po.pdf").name
        po_path.write_bytes(await po.read())
        ack_x = None
        if ack is not None:
            ack_path = Path(d) / Path(ack.filename or "ack.pdf").name
            ack_path.write_bytes(await ack.read())
            ack_x = ingest.extract(ingest.normalize_file(ack_path))
        r = verify.verify(ingest.extract(ingest.normalize_file(po_path)), ack_x)
    return r.for_agent()


