import { useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import { api } from '../api'
import type { DocLine, ErpRow, Extracted, Finding, RunDetail, Val } from '../api'
import { Card, FindingBadge, KeyValues, LabelBadge, RecommendationBadge, Table, fmtDate, fmtValue } from '../ui'

// One verification of one order, read as steps: the email, the customer's PO, the sales order,
// the customer's terms as the agent read them, then the checks and everything that went wrong.

function V({ v }: { v: Val | string | undefined | null }) {
  if (v === null || v === undefined) return <span className="text-slate-400">—</span>
  if (typeof v === 'string') return <>{v}</>
  if (!v.raw) return <span className="text-slate-400">—</span>
  const where = v.loc ? [v.loc.page ? `p${v.loc.page}` : '', v.loc.where ?? ''].filter(Boolean).join(' · ') : ''
  return (
    <span title={where ? `Read from ${where}` : undefined} className="whitespace-pre-line">
      {v.raw}
    </span>
  )
}

function Step({ n, title, subtitle, children, tone = 'slate' }: { n: number; title: string; subtitle?: ReactNode; children: ReactNode; tone?: 'slate' | 'red' | 'emerald' }) {
  const dot = tone === 'red' ? 'bg-red-600' : tone === 'emerald' ? 'bg-emerald-600' : 'bg-slate-800'
  return (
    <li className="relative pl-12">
      <span className={`absolute left-0 top-0 flex h-8 w-8 items-center justify-center rounded-full text-sm font-semibold text-white ${dot}`}>{n}</span>
      <span className="absolute left-4 top-9 bottom-0 w-px bg-slate-200" aria-hidden />
      <div className="pb-8">
        <h2 className="text-base font-semibold text-slate-900">{title}</h2>
        {subtitle && <p className="mt-0.5 text-sm text-slate-500">{subtitle}</p>}
        <div className="mt-3 space-y-3">{children}</div>
      </div>
    </li>
  )
}

const HEADER_FIELDS: [string, string][] = [
  ['doc_number', 'Number'],
  ['doc_date', 'Date'],
  ['customer_po_ref', 'Customer PO'],
  ['customer_name', 'Customer'],
  ['customer_id', 'Customer id'],
  ['buyer_name', 'Buyer'],
  ['buyer_email', 'Buyer email'],
  ['payment_terms', 'Payment terms'],
  ['ship_via', 'Ship via'],
  ['incoterm', 'Shipping terms'],
  ['carrier_account', 'Freight account'],
  ['freight_terms', 'Freight terms'],
  ['ship_option', 'Ship option'],
  ['currency', 'Currency'],
  ['ship_to', 'Ship to'],
  ['bill_to', 'Bill to'],
]

function DocumentView({ x, kind }: { x: Extracted; kind: 'po' | 'ack' }) {
  const h = x.doc.header
  const rows = HEADER_FIELDS.filter(([k]) => {
    const v = h[k]
    return typeof v === 'object' && v?.raw
  }).map(([k, label]) => [label, <V v={h[k] as Val} />] as [string, ReactNode])
  const lineRows = x.doc.lines.map((l: DocLine, i) => [
    <V v={l.line_no.raw ? l.line_no : String(i + 1)} />,
    <span className="font-mono text-xs"><V v={l.mpn} /></span>,
    <V v={l.manufacturer} />,
    <V v={l.customer_pn} />,
    <span className="tabular-nums"><V v={l.qty} /></span>,
    <span className="tabular-nums"><V v={l.unit_price} /></span>,
    <span className="tabular-nums"><V v={l.extended} /></span>,
    <V v={l.required_date} />,
    ...(kind === 'ack' ? [<V v={l.ship_date} />] : []),
  ])
  return (
    <Card
      title={kind === 'po' ? "Customer's purchase order" : 'Our sales order acknowledgement'}
      subtitle={<>{x.source} · read as {x.method}{x.links.length ? <> · links: {x.links.map((l) => <a key={l} href={l} target="_blank" rel="noreferrer" className="text-blue-700 underline">{new URL(l).hostname}</a>)}</> : null}</>}
    >
      <KeyValues rows={rows} />
      <div className="mt-4">
        <Table head={['Line', 'Part number', 'Manufacturer', 'Cust. part', 'Qty', 'Unit price', 'Extended', 'Required', ...(kind === 'ack' ? ['Est. ship'] : [])]} rows={lineRows} />
      </div>
      {x.doc.notes.length > 0 && (
        <div className="mt-4">
          <h4 className="text-xs font-semibold uppercase tracking-wide text-slate-500">Notes and conditions</h4>
          <ul className="mt-1 list-disc space-y-1 pl-5 text-sm text-slate-700">
            {x.doc.notes.map((n, i) => <li key={i}><V v={n} /></li>)}
          </ul>
        </div>
      )}
      {x.warnings.length > 0 && <p className="mt-3 rounded bg-amber-50 px-3 py-2 text-xs text-amber-800">Extraction warnings: {x.warnings.join('; ')}</p>}
    </Card>
  )
}

function ErpLines({ lines }: { lines: ErpRow[] }) {
  return (
    <Table
      head={['Line', 'Part number', 'Mfr', 'Qty', 'Unit price', 'Our cost', 'Required', 'Vendor', 'Cust. part']}
      rows={lines.map((l) => [
        fmtValue(l.lin_no),
        <span className="font-mono text-xs">{fmtValue(l.item_no)}</span>,
        fmtValue(l.manu_no),
        <span className="tabular-nums">{fmtValue(l.ord_qty)}</span>,
        <span className="tabular-nums">{fmtValue(l.unit_price)}</span>,
        <span className="tabular-nums">{fmtValue(l.unit_cost)}</span>,
        fmtValue(l.req_date),
        fmtValue(l.vend_no),
        fmtValue(l.cust_itmno),
      ])}
    />
  )
}

const ISSUE_ORDER: Finding['status'][] = ['fail', 'needs_approval', 'needs_review', 'unverifiable']
const ISSUE_TITLES: Record<string, string> = {
  fail: 'Failed — must be fixed before release',
  needs_approval: 'Needs approval',
  needs_review: 'Needs a person to review',
  unverifiable: "Couldn't be verified",
}

function FindingItem({ f }: { f: Finding }) {
  const [open, setOpen] = useState(false)
  return (
    <li className="rounded-lg border border-slate-200 bg-white">
      <button onClick={() => setOpen(!open)} className="flex w-full items-start gap-3 px-3 py-2 text-left">
        <FindingBadge value={f.status} />
        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium text-slate-900">
            {f.title} <span className="font-normal text-slate-400">· checklist {f.checklist_ref}{f.severity !== 'info' ? ` · ${f.severity}` : ''}</span>
          </p>
          <p className="text-sm text-slate-600">{f.message}</p>
        </div>
        <span className="text-xs text-slate-400">{open ? 'Hide' : 'Evidence'}</span>
      </button>
      {open && f.evidence.length > 0 && (
        <div className="border-t border-slate-100 px-3 py-2">
          <Table
            head={['', 'Value', 'Where it came from']}
            rows={f.evidence.map((e) => [<span className="font-medium text-slate-700">{e.label}</span>, <span className="whitespace-pre-line">{e.value ?? '—'}</span>, <span className="text-xs text-slate-500">{e.source}</span>])}
          />
        </div>
      )}
    </li>
  )
}

export function OrderDetail({ runId }: { runId: number }) {
  const [d, setD] = useState<RunDetail | null>(null)
  const [err, setErr] = useState<string | null>(null)
  const [showChecklist, setShowChecklist] = useState(false)

  useEffect(() => {
    setD(null)
    setErr(null)
    api.runDetail(runId).then(setD).catch((e: Error) => setErr(e.message))
  }, [runId])

  const issues = useMemo(() => {
    if (!d) return {} as Record<string, Finding[]>
    const out: Record<string, Finding[]> = {}
    for (const f of d.findings) {
      const relevant = f.status !== 'unverifiable' || f.severity === 'high' || f.severity === 'medium'
      if (ISSUE_ORDER.includes(f.status) && relevant) (out[f.status] ??= []).push(f)
    }
    return out
  }, [d])

  if (err) return <p className="p-6 text-sm text-red-700">Could not load this order: {err}</p>
  if (!d) return <p className="p-6 text-sm text-slate-500">Loading…</p>

  const so = d.erp?.so
  const cust = d.erp?.customer
  const ackH = d.ack?.doc.header
  const carry = d.findings.filter((f) => f.status === 'manual')
  const passed = d.findings.filter((f) => f.status === 'pass').length
  const exposure = (d.erp?.credit.open_orders ?? 0) + Math.max(d.erp?.credit.ar_balance ?? 0, 0)
  const issueCount = Object.values(issues).reduce((n, xs) => n + xs.length, 0)

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center gap-3">
        <h1 className="text-xl font-semibold text-slate-900">{d.run.customer ?? 'Unknown customer'}</h1>
        <RecommendationBadge value={d.recommendation} />
        <span className="text-sm text-slate-500">
          SO {d.run.so_number ?? '—'} · PO {d.run.cust_po ?? '—'} · verified {fmtDate(d.run.created)}
        </span>
      </div>

      <ol>
        <Step n={1} title="Purchase order email" subtitle={d.email ? `${d.email.sender} · ${fmtDate(d.email.received)}` : 'Verified from files, not from an email'}>
          {d.email ? (
            <Card title={d.email.subject ?? '(no subject)'} right={<LabelBadge value={d.email.label ?? null} />}>
              <KeyValues
                rows={[
                  ['From', d.email.sender ?? '—'],
                  ['Received', fmtDate(d.email.received)],
                  ['Triage', <>{(d.email.label ?? '').replace(/_/g, ' ')} {d.email.triage_confidence != null && <span className="text-slate-400">({Math.round(d.email.triage_confidence * 100)}%)</span>}</>],
                  ['Why', d.email.triage_reasons ?? '—'],
                  ['Agent steps', d.email.agent?.steps.map((s) => s.tool).join(' → ') ?? '—'],
                ]}
              />
              {d.email.reply_draft && (
                <details className="mt-3 rounded-lg bg-slate-50 px-3 py-2">
                  <summary className="cursor-pointer text-sm font-medium text-slate-700">
                    Reply drafted to {d.email.reply_draft.to}{d.email.reply_draft.dry_run ? ' (dry run, not sent)' : ''}
                  </summary>
                  <p className="mt-2 text-sm font-medium">{d.email.reply_draft.subject}</p>
                  <pre className="mt-1 whitespace-pre-wrap font-sans text-sm text-slate-700">{d.email.reply_draft.body}</pre>
                </details>
              )}
            </Card>
          ) : (
            <p className="text-sm text-slate-500">This order was checked from local documents (batch run), so there is no email record.</p>
          )}
        </Step>

        <Step n={2} title="Customer's purchase order" subtitle="What the customer asked for, read verbatim from their document. Hover a value to see where it was read.">
          {d.po ? <DocumentView x={d.po} kind="po" /> : <p className="text-sm text-slate-500">No PO document.</p>}
        </Step>

        <Step n={3} title="Sales order" subtitle="What we entered: the ERP sales order, and the acknowledgement we send the customer.">
          <Card title={`ERP sales order ${so ? fmtValue(so.order_no) : ''}`} subtitle="ord_hedr / ord_detl, as read when the order was checked">
            {so ? (
              <>
                <KeyValues
                  rows={[
                    ['Customer', `${fmtValue(cust?.cust_name)} (${fmtValue(so.cust_no)})`],
                    ['Customer PO', fmtValue(so.cust_po)],
                    ['Order date', fmtValue(so.order_dt)],
                    ['Status', fmtValue(so.status)],
                    ['Payment terms', fmtValue(so.terms_code)],
                    ['Quote', fmtValue(so.quote_no)],
                  ]}
                />
                <div className="mt-4"><ErpLines lines={d.erp?.lines ?? []} /></div>
              </>
            ) : (
              <p className="text-sm text-slate-500">No sales order found in the ERP.</p>
            )}
          </Card>
          {d.ack && ackH && <DocumentView x={d.ack} kind="ack" />}
          {cust && (
            <Card title="Customer account" subtitle="customer master and credit position">
              <KeyValues
                rows={[
                  ['Master terms', fmtValue(cust.terms_code)],
                  ['Credit limit', fmtValue(cust.crdt_limit)],
                  ['Exposure', `${exposure.toLocaleString(undefined, { maximumFractionDigits: 2 })} (open orders ${fmtValue(d.erp?.credit.open_orders)} + AR ${fmtValue(d.erp?.credit.ar_balance)})`],
                  ['Ship via / FOB', `${fmtValue(cust.ship_via)} / ${fmtValue(cust.fob_code)}`],
                  ['Address', [cust.cust_addr1, cust.cust_city, cust.cust_state, cust.cust_zip, cust.cust_cntry].filter(Boolean).join(', ')],
                ]}
              />
              {d.erp?.supply && d.erp.supply.length > 0 && (
                <div className="mt-4">
                  <h4 className="mb-1 text-xs font-semibold uppercase tracking-wide text-slate-500">Supplier PO lines bought for this order</h4>
                  <Table
                    head={['PO', 'Line', 'For SO line', 'Vendor', 'Qty', 'Cost', 'Due', 'Origin']}
                    rows={d.erp.supply.map((p) => [fmtValue(p.po_no), fmtValue(p.lin_no), fmtValue(p.so_lin_no), fmtValue(p.vend_no), fmtValue(p.ord_qty), fmtValue(p.unit_cost), fmtValue(p.due_date), fmtValue(p.src_cntry)])}
                  />
                </div>
              )}
            </Card>
          )}
        </Step>

        <Step n={4} title="Customer terms, as the agent read them" subtitle="Clauses from the customer master, the PO and its conditions. Each one is checked by a rule in step 5.">
          <Card title={`${d.requirements.length} clauses`}>
            <Table
              head={['Clause', 'Details', 'Text', 'Source']}
              rows={d.requirements.map((r) => [
                <span className="font-medium">{r.clause_type.replace(/_/g, ' ')}</span>,
                <span className="text-xs text-slate-600">{Object.entries(r.params).filter(([, v]) => v !== null && v !== undefined && v !== '').map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(', ') : String(v)}`).join(' · ') || '—'}</span>,
                <span className="text-slate-700">{r.quote}</span>,
                <span className="text-xs text-slate-500">{r.source} · {r.scope}</span>,
              ])}
              empty="No customer-specific terms."
            />
          </Card>
        </Step>

        <Step n={5} title="Checks and what went wrong" subtitle={`${issueCount} issue${issueCount === 1 ? '' : 's'} · ${passed} checks passed · ${carry.length} requirements to carry forward`} tone={d.recommendation === 'release' ? 'emerald' : 'red'}>
          <div className="rounded-xl border border-slate-200 bg-white px-4 py-3">
            <div className="flex items-center gap-2">
              <span className="text-sm font-semibold">Recommendation</span>
              <RecommendationBadge value={d.recommendation} />
            </div>
            <ul className="mt-2 list-disc space-y-1 pl-5 text-sm text-slate-700">
              {d.reasons.slice(0, 8).map((r, i) => <li key={i}>{r}</li>)}
            </ul>
            {d.problems.length > 0 && <p className="mt-2 text-xs text-amber-700">Notes: {d.problems.join('; ')}</p>}
          </div>

          {d.revision && (
            <Card title="Revision of an earlier PO" subtitle={d.revision.how}>
              <Table head={['Where', 'Field', 'Was', 'Now']} rows={(d.revision.changes ?? []).map((c) => [c.where, c.field, c.old ?? '—', c.new ?? '—'])} empty="No differences." />
              {d.revision.issues && (
                <div className="mt-3 grid gap-2 text-sm sm:grid-cols-3">
                  {(['resolved', 'new', 'still_open'] as const).map((k) => (
                    <div key={k}>
                      <p className="font-medium capitalize">{k.replace('_', ' ')}</p>
                      <ul className="list-disc pl-5 text-slate-600">{(d.revision?.issues?.[k] ?? []).map((x) => <li key={x}>{x.split(':')[0]}</li>)}</ul>
                    </div>
                  ))}
                </div>
              )}
            </Card>
          )}

          {ISSUE_ORDER.filter((s) => issues[s]?.length).map((s) => (
            <div key={s}>
              <h3 className="mb-2 text-sm font-semibold text-slate-800">{ISSUE_TITLES[s]} ({issues[s].length})</h3>
              <ul className="space-y-2">{issues[s].map((f, i) => <FindingItem key={`${f.check_id}-${f.line}-${i}`} f={f} />)}</ul>
            </div>
          ))}

          {carry.length > 0 && (
            <details className="rounded-xl border border-slate-200 bg-white px-4 py-3">
              <summary className="cursor-pointer text-sm font-semibold">Carry forward when sourcing and shipping ({carry.length})</summary>
              <ul className="mt-2 space-y-1 text-sm text-slate-700">{carry.map((f, i) => <li key={i}><span className="font-medium">{f.title}</span> — {f.message}</li>)}</ul>
            </details>
          )}

          <div className="rounded-xl border border-slate-200 bg-white px-4 py-3">
            <button onClick={() => setShowChecklist(!showChecklist)} className="text-sm font-semibold text-slate-800">
              {showChecklist ? 'Hide' : 'Show'} our order checklist ({d.checklist.length} items)
            </button>
            {showChecklist && (
              <div className="mt-3">
                <Table
                  head={['Ref', 'Item', 'Status', 'Checks']}
                  rows={d.checklist.map((c) => [c.ref, <span>{c.text}{c.added && <span className="text-slate-400"> (added)</span>}</span>, <FindingBadge value={c.status} />, c.automated ? String(c.findings) : <span className="text-xs text-slate-500">not automated: {c.manual_reason ?? 'no check applies'}</span>])}
                />
              </div>
            )}
          </div>

          {d.erp_actions.length > 0 && (
            <details className="rounded-xl border border-slate-200 bg-white px-4 py-3">
              <summary className="cursor-pointer text-sm font-semibold">ERP actions ({d.erp_actions.filter((a) => a.dry_run).length} planned, dry run)</summary>
              <ul className="mt-2 space-y-2 text-xs">
                {d.erp_actions.map((a) => (
                  <li key={a.id}>
                    <span className="font-medium">{a.kind.replace('_', ' ')}</span> {a.dry_run ? '(planned, not executed)' : '(applied)'} · {fmtDate(a.created)}
                    {a.detail.note && <span className="text-slate-500"> — {a.detail.note}</span>}
                    <pre className="mt-1 overflow-x-auto rounded bg-slate-50 p-2 text-[11px] text-slate-600">{a.detail.statements[0]?.sql}</pre>
                  </li>
                ))}
              </ul>
            </details>
          )}
        </Step>
      </ol>
    </div>
  )
}

