        po_path, ack_path = _LOCAL[message_id]["po_path"], _LOCAL[message_id]["ack_path"]
        message_id = None
    if message_id:
        docs, notes = _all_docs(mail.get_email(message_id))
        pos = [x for x in docs if x.doc.header.doc_type == "supplier_po"]
