    result = json.loads(path.read_text())
    findings = [Finding.model_validate(f) for f in result["findings"]]
    if not 0 <= index < len(findings):
        return {"error": f"no finding {index} in run {run_id}"}
    f = findings[index]
    current = f.original_status or f.status
    if current not in RESOLVABLE:
        return {"error": f"finding {index} is {current.value}: only needs_review and unverifiable items can be resolved by the agent; "
                         "failures and approvals stay with a person"}
