"""Writes to the ERP: record check results, put an order on hold.

Dry-run by default (ERP_DRY_RUN=1): each action is planned, with its exact SQL, and logged to
the state store (visible at GET /erp-actions) but not executed. With ERP_DRY_RUN=0 the same
statements run in one transaction. Our own tables carry an `agent_` prefix; the only change to
an ERP table is the order status, and only from open (O, I) to hold (H).
"""
from __future__ import annotations

import json

from . import config, db, state

SCHEMA = [
    "create table if not exists worktrial.agent_check_result (id bigserial primary key, so_number integer, cust_no text, "
    "cust_po text, recommendation text, counts jsonb, report_path text, message_id text, created_at timestamptz default now())",
    "create table if not exists worktrial.agent_check_issue (result_id bigint references worktrial.agent_check_result(id), "
    "check_id text, checklist_ref text, title text, status text, severity text, line integer, message text)",
    "create table if not exists worktrial.agent_order_hold (id bigserial primary key, so_number integer, previous_status text, "
    "reason text, message_id text, created_at timestamptz default now())",
]

ISSUES = ("fail", "needs_approval", "needs_review", "unverifiable")


def record_result(result, message_id: str | None = None) -> dict:
    o = result.order
    if not o.get("so_number"):
        return {"skipped": "no SO"}
    head = ("insert into worktrial.agent_check_result (so_number, cust_no, cust_po, recommendation, counts, report_path, message_id) "
            "values (%s, %s, %s, %s, %s, %s, %s) returning id",
            [o["so_number"], o.get("cust_no"), o.get("cust_po"), result.recommendation, json.dumps(result.counts), result.report_path, message_id])
    issues = [("insert into worktrial.agent_check_issue (result_id, check_id, checklist_ref, title, status, severity, line, message) "
               "values (%(result_id)s, %s, %s, %s, %s, %s, %s, %s)",
               [f.check_id, f.checklist_ref, f.title, f.status.value, f.severity, f.line, f.message])
              for f in result.findings if f.status.value in ISSUES]

    def run(cur):
        cur.execute(head[0], head[1])
        rid = cur.fetchone()["id"]
        for sql, params in issues:
            cur.execute(sql.replace("%(result_id)s", "%s"), [rid, *params])
        return {"result_id": rid}

    return _apply("record_result", o["so_number"], [head] + issues, run, message_id)


def hold_order(so_number: int, reason: str, message_id: str | None = None) -> dict:
    """Put an open order on hold (status O or I -> H) and keep the reason."""
    with db.connect() as conn:
        row = db.Erp(conn).row("select trim(status) as status from ord_hedr where order_no = %s", (so_number,))
    if not row:
        return {"skipped": f"SO {so_number} not found"}
    if row["status"] not in ("O", "I"):
        return {"skipped": f"SO {so_number} has status {row['status']}; only open orders (O, I) are put on hold"}
    update = ("update worktrial.ord_hedr set status = 'H', updt_dt = now(), updt_id = 'AGENT' where order_no = %s and trim(status) in ('O', 'I')",
              [so_number])
    log = ("insert into worktrial.agent_order_hold (so_number, previous_status, reason, message_id) values (%s, %s, %s, %s)",
           [so_number, row["status"], reason, message_id])

    def run(cur):
        cur.execute(*update)
        cur.execute(*log)
        return {"previous_status": row["status"]}

    return _apply("hold_order", so_number, [update, log], run, message_id, reason)


def _apply(kind: str, so_number, statements, run, message_id=None, note=None) -> dict:
    planned = [{"sql": s, "params": p} for s, p in statements]
    if config.ERP_DRY_RUN:
        state.add_erp_action(kind, so_number, True, {"statements": planned, "note": note}, message_id)
        return {"dry_run": True, "kind": kind, "so_number": so_number, "statements": len(planned)}
    with db.connect(read_only=False) as conn:
        with conn.cursor() as cur:
            for ddl in SCHEMA:
                cur.execute(ddl)
            out = run(cur)
        conn.commit()
    state.add_erp_action(kind, so_number, False, {"statements": planned, "note": note, "result": out}, message_id)
    return {"dry_run": False, "kind": kind, "so_number": so_number, **out}

